public class Map
{
    const string MAP_TEMPLATE_IMAGE = "";
    string name = "Map";
    string mapImage;
    public string Name { get { return name; } set { name = value; } }
    public string MapImage { get { return mapImage; } set { mapImage = value; } }

    public Map(string name) 
    {
        this.name = name;
        this.mapImage = MAP_TEMPLATE_IMAGE;
    }
}